      organizationId: 12345,
      personId: 67890,
      dealId: 54321,
    });
  });
});

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    pipedriveApiToken: 'test-token',
    fieldIds: {
      email: 'SMEUb7VJz92Q',
      name: 'JwWggjAKtOkA',
      company: 'some_company_field_id',
      phone: 'some_phone_field_id',
    },
    defaultStageId: 1,
  };

  it('creates organization, person, and deal with correct request bodies', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ success: true, data: { id: 12345 } }, 201);
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ success: true, data: { id: 67890 } }, 201);
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ success: true, data: { id: 54321 } }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: TypeformPayload = {
      event_id: 'test',
      event_type: 'form_response',
      form_response: {
        form_id: 'test',
        token: 'test',
        submitted_at: '2023-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'laura@example.com', field: { id: 'SMEUb7VJz92Q', type: 'email' } },
          { type: 'text', text: 'Laura', field: { id: 'JwWggjAKtOkA', type: 'short_text' } },
          { type: 'text', text: 'Acme Corp', field: { id: 'some_company_field_id', type: 'short_text' } },
          { type: 'text', text: '+1234567890', field: { id: 'some_phone_field_id', type: 'short_text' } },
        ],
      },
    };

    const result = await handle(payload, { ...baseConfig, fetch });
    expect(result).toEqual({ organizationId: 12345, personId: 67890, dealId: 54321 });

    // Check organization creation call
    expect(calls[0].method).toBe('POST');
    expect(calls[0].url).toBe('https://api.pipedrive.com/v2/organizations');
    expect(calls[0].json).toEqual({ title: 'Acme Corp' });
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-token');

    // Check person creation call
    expect(calls[1].method).toBe('POST');
    expect(calls[1].url).toBe('https://api.pipedrive.com/v2/persons');
    expect(calls[1].json).toEqual({
      name: 'Laura',
      email: [{ value: 'laura@example.com', primary: true, label: 'work' }],
      phone: [{ value: '+1234567890', primary: true, label: 'work' }],
      org_id: 12345,
    });
    expect(calls[1].headers.get('authorization')).toBe('Bearer test-token');

    // Check deal creation call
    expect(calls[2].method).toBe('POST');
    expect(calls[2].url).toBe('https://api.pipedrive.com/v2/deals');
    expect(calls[2].json).toEqual({
      title: 'Deal from Laura',
      person_id: 67890,
      stage_id: 1,
    });
    expect(calls[2].headers.get('authorization')).toBe('Bearer test-token');
  });

  it('uses configured field IDs for mapping', async () => {
    const customFieldIds = {
      email: 'email_field',
      name: 'name_field',
      company: 'company_field',
      phone: 'phone_field',
    };
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ success: true, data: { id: 1 } }, 201);
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ success: true, data: { id: 2 } }, 201);
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ success: true, data: { id: 3 } }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: TypeformPayload = {
      event_id: 'test',
      event_type: 'form_response',
      form_response: {
        form_id: 'test',
        token: 'test',
        submitted_at: '2023-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'test@example.com', field: { id: 'email_field', type: 'email' } },
          { type: 'text', text: 'Test User', field: { id: 'name_field', type: 'short_text' } },
          { type: 'text', text: 'Test Company', field: { id: 'company_field', type: 'short_text' } },
          { type: 'text', text: '+1987654321', field: { id: 'phone_field', type: 'short_text' } },
        ],
      },
    };

    await handle(payload, { ...baseConfig, fieldIds: customFieldIds, fetch });
    expect(calls[0].json).toEqual({ title: 'Test Company' });
    expect(calls[1].json).toEqual({
      name: 'Test User',
      email: [{ value: 'test@example.com', primary: true, label: 'work' }],
      phone: [{ value: '+1987654321', primary: true, label: 'work' }],
      org_id: 1,
    });
  });

  it('throws descriptive error when required field is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ success: true, data: { id: 1 } }, 201));
    const payload: TypeformPayload = {
      event_id: 'test',
      event_type: 'form_response',
      form_response: {
        form_id: 'test',
        token: 'test',
        submitted_at: '2023-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'laura@example.com', field: { id: 'SMEUb7VJz92Q', type: 'email' } },
          // missing name
          { type: 'text', text: 'Acme Corp', field: { id: 'some_company_field_id', type: 'short_text' } },
          { type: 'text', text: '+1234567890', field: { id: 'some_phone_field_id', type: 'short_text' } },
        ],
      },
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required fields in Typeform payload: name'
    );
  });

  it('throws error with status and endpoint on non-2xx response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    const payload: TypeformPayload = {
      event_id: 'test',
      event_type: 'form_response',
      form_response: {
        form_id: 'test',
        token: 'test',
        submitted_at: '2023-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'laura@example.com', field: { id: 'SMEUb7VJz92Q', type: 'email' } },
          { type: 'text', text: 'Laura', field: { id: 'JwWggjAKtOkA', type: 'short_text' } },
          { type: 'text', text: 'Acme Corp', field: { id: 'some_company_field_id', type: 'short_text' } },
          { type: 'text', text: '+1234567890', field: { id: 'some_phone_field_id', type: 'short_text' } },
        ],
      },
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Pipedrive API error: 401 Unauthorized for https://api.pipedrive.com/v2/organizations'
    );
  });

  it('uses defaultStageId from config for deal creation', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ success: true, data: { id: 1 } }, 201);
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ success: true, data: { id: 2 } }, 201);
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ success: true, data: { id: 3 } }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: TypeformPayload = {
      event_id: 'test',
      event_type: 'form_response',
      form_response: {
        form_id: 'test',
        token: 'test',
        submitted_at: '2023-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'laura@example.com', field: { id: 'SMEUb7VJz92Q', type: 'email' } },
          { type: 'text', text: 'Laura', field: { id: 'JwWggjAKtOkA', type: 'short_text' } },
          { type: 'text', text: 'Acme Corp', field: { id: 'some_company_field_id', type: 'short_text' } },
          { type: 'text', text: '+1234567890', field: { id: 'some_phone_field_id', type: 'short_text' } },
        ],
      },
    };

    await handle(payload, { ...baseConfig, defaultStageId: 5, fetch });
    expect(calls[2].json).toEqual({
      title: 'Deal from Laura',
      person_id: 2,
      stage_id: 5,
    });
  });
});

# Typeform to Pipedrive Connector

This connector processes a Typeform form submission webhook and creates three linked resources in Pipedrive:
1. An **Organization** (using the company name)
2. A **Person** (using the contact's name, email, phone, linked to the organization)
3. A **Deal** (titled "Deal from {name}", linked to the person, using a configurable default stage)

## Configuration

The connector requires the following configuration parameters (typically supplied via environment variables):

| Parameter | Environment Variable | Description |
|-----------|----------------------|-------------|
| `pipedriveApiToken` | `PIPEDRIVE_API_TOKEN` | Pipedrive API token (Bearer token). |
| `fieldIds.email` | `TYPEFORM_EMAIL_FIELD_ID` | Typeform field ID for the email answer. |
| `fieldIds.name` | `TYPEFORM_NAME_FIELD_ID` | Typeform field ID for the name answer. |
| `fieldIds.company` | `TYPEFORM_COMPANY_FIELD_ID` | Typeform field ID for the company answer. |
| `fieldIds.phone` | `TYPEFORM_PHONE_FIELD_ID` | Typeform field ID for the phone answer. |
| `defaultStageId` (optional) | `PIPEDRIVE_DEFAULT_STAGE_ID` | Default stage ID for deal creation (defaults to `1`). |

All secrets must be provided via the config object at runtime; they are never hard‑coded.

## Usage Example

```typescript
import { handle, ConnectorConfig, TypeformPayload } from './connector';

const config: ConnectorConfig = {
  pipedriveApiToken: process.env.PIPEDRIVE_API_TOKEN!,
  fieldIds: {
    email: process.env.TYPEFORM_EMAIL_FIELD_ID!,
    name: process.env.TYPEFORM_NAME_FIELD_ID!,
    company: process.env.TYPEFORM_COMPANY_FIELD_ID!,
    phone: process.env.TYPEFORM_PHONE_FIELD_ID!,
  },
  defaultStageId: Number(process.env.PIPEDRIVE_DEFAULT_STAGE_ID ?? 1),
};

// In your webhook handler (e.g., Express, Fastify, AWS Lambda):
app.post('/typeform-webhook', async (req, res) => {
  try {
    const payload = req.body as TypeformPayload;
    const result = await handle(payload, config);
    res.json({ success: true, ...result });
  } catch (err) {
    console.error(err);
    res.status(500).json({ success: false, error: err.message });
  }
});
```

## Assumptions

1. The Typeform form includes fields for email, name, company, and phone. Their field IDs are known and configured via `fieldIds`.
2. The Pipedrive API token has permissions to create organizations, persons, and deals.
3. The Pipedrive pipeline has at least one stage; the connector uses `defaultStageId` (default `1`) for the deal's `stage_id`.
4. The incoming webhook payload follows the [Typeform webhook example](https://www.typeform.com/developers/webhooks/example-payload) structure (an `answers` array with `field.id` matching the configured IDs).
5. The connector does not implement any webhook signature verification; the hosting platform must secure the endpoint (HTTPS, optional payload signing).
6. All Pipedrive API calls use the `Authorization: Bearer <token>` header (also accepts `Token <token>`).
7. The connector makes three sequential POST requests; if any step fails, an error is thrown and no further calls are made.

